const listScheduleRuleRevisionsForRangeByActor = `-- name: ListScheduleRuleRevisionsForRangeByActor :many
WITH active_revisions AS (
    SELECT r.id, r.rule_id, r.user_id, r.revision, r.effective_from, r.recurrence_anchor_date, r.local_start, r.local_end, r.all_day, r.timezone, r.frequency, r.interval_count, r.weekdays, r.end_date, r.title, r.description, r.location, r.project_id, r.assignee_id, r.superseded_at, r.cutoff_after, r.changed_by, r.created_at,
           LEAD(r.effective_from) OVER (PARTITION BY r.rule_id ORDER BY r.effective_from, r.revision) AS next_effective_from
    FROM schedule_rule_revisions r
    JOIN schedule_rules b ON b.id = r.rule_id AND b.deleted_at IS NULL
    WHERE r.superseded_at IS NULL
)
SELECT r.id, r.rule_id, r.user_id, r.revision, r.effective_from, r.recurrence_anchor_date, r.local_start, r.local_end, r.all_day, r.timezone, r.frequency, r.interval_count, r.weekdays, r.end_date, r.title, r.description, r.location, r.project_id, r.assignee_id, r.superseded_at, r.cutoff_after, r.changed_by, r.created_at, r.next_effective_from,
       CASE WHEN r.cutoff_after IS NULL THEN r.next_effective_from - 1
            WHEN r.next_effective_from IS NULL THEN r.cutoff_after
            ELSE LEAST(r.cutoff_after, r.next_effective_from - 1) END AS effective_until
FROM active_revisions r
JOIN schedule_rules b ON b.id = r.rule_id
WHERE r.effective_from <= ($1::timestamptz AT TIME ZONE r.timezone)::date
  AND (r.cutoff_after IS NULL OR r.cutoff_after >=
       ($2::timestamptz AT TIME ZONE r.timezone)::date - (r.local_end::date - r.local_start::date))
  AND (r.next_effective_from IS NULL OR r.next_effective_from - 1 >=
       ($2::timestamptz AT TIME ZONE r.timezone)::date - (r.local_end::date - r.local_start::date))
  AND (r.end_date IS NULL OR r.end_date >=
       ($2::timestamptz AT TIME ZONE r.timezone)::date
       - (r.local_end::date - r.local_start::date))
  AND schedule_rule_has_permission_at(b.id, r.effective_from, $3::text, 'schedule', 'read')
ORDER BY b.id, r.effective_from, r.revision
`

